const $=s=>document.querySelector(s), esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const paths={home:'M3 10l9-7 9 7v10a1 1 0 0 1-1 1h-5v-7H9v7H4a1 1 0 0 1-1-1z',book:'M4 4h6a3 3 0 0 1 2 1 3 3 0 0 1 2-1h6v16h-6a3 3 0 0 0-2 1 3 3 0 0 0-2-1H4z M12 5v16',record:'M7 3h10v3H7z M6 5H4v16h16V5h-2 M8 11h8 M8 15h8',spark:'M12 2l2.6 7.4L22 12l-7.4 2.6L12 22l-2.6-7.4L2 12l7.4-2.6z',settings:'M12 8a4 4 0 1 0 0 8 4 4 0 0 0 0-8 M9 3h6l1 3 3 1 2 5-2 5-3 1-1 3H9l-1-3-3-1-2-5 2-5 3-1z',water:'M12 2C9 7 5 11 5 15a7 7 0 0 0 14 0c0-4-4-8-7-13z M8 15a4 4 0 0 0 4 4',camera:'M3 7h4l2-3h6l2 3h4v14H3z M12 10a4 4 0 1 0 0 8 4 4 0 0 0 0-8',edit:'M14 4l6 6 M4 14L16 2l6 6-12 12-7 1z',plus:'M12 5v14 M5 12h14',arrow:'M5 12h14 M14 7l5 5-5 5',close:'M6 6l12 12 M18 6L6 18',chart:'M4 3v18h17 M8 16v-5 M13 16V7 M18 16V4',leaf:'M20 3C6 2 2 8 5 15c4 7 15 4 15-12z M5 20L16 8',check:'M5 12l4 4L19 6',shield:'M12 2l9 4v7c0 5-9 9-9 9s-9-4-9-9V6z M8 12l3 3 5-6',clock:'M12 3a9 9 0 1 0 0 18 9 9 0 0 0 0-18 M12 7v5l3 2',upload:'M12 16V3 M7 8l5-5 5 5 M4 15v6h16v-6',send:'M3 3l19 9-19 9 3-9z M6 12h16',user:'M12 3a4 4 0 1 0 0 8 4 4 0 0 0 0-8 M4 21v-3c0-7 16-7 16 0v3',trash:'M3 6h18 M9 6V3h6v3 M6 6l1 15h10l1-15 M10 10v7 M14 10v7'};
const ic=(n)=>`<svg class="icon" viewBox="0 0 24 24" aria-hidden="true"><path d="${paths[n]||paths.spark}"/></svg>`;
function today(){const d=new Date();return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`}function timeNow(){return new Date().toLocaleTimeString('zh-CN',{hour:'2-digit',minute:'2-digit',hour12:false})}const day=today();
const init={version:21,settings:{name:'奥博',role:'在校学生',language:'zh',calorieGoal:1900,proteinGoal:85,waterGoal:1800,compact:false,hideEnergy:false,reminder:true,aiContext:true},meals:[{id:1,date:day,type:'早餐',time:'08:15',food:'全麦三明治、牛奶、香蕉',cal:480,protein:22,carbs:63,fat:15,before:3,after:4,score:7,satisfaction:4,cost:18,duration:20,icon:'🥪',demo:true},{id:2,date:day,type:'午餐',time:'12:30',food:'米饭、香煎鸡胸肉、西兰花',cal:800,protein:36,carbs:98,fat:29,before:3,after:4,score:8,satisfaction:4,cost:28,duration:35,icon:'🥗',demo:true}],water:[{id:11,date:day,time:'08:30',amount:300,demo:true},{id:12,date:day,time:'10:20',amount:300,demo:true},{id:13,date:day,time:'12:45',amount:300,demo:true}],quota:{date:day,chat:0,photo:0},chat:[],bookmarks:[]};
let state;try{state=JSON.parse(localStorage.getItem('shike-v21'));if(!state||state.version!==21){state=structuredClone(init);const old=JSON.parse(localStorage.getItem('shike-meals-v2'));if(Array.isArray(old)&&old.length)state.meals=old.map(m=>({...m,date:day,before:3,after:m.after==='未记录'?null:4,carbs:null,fat:null,demo:m.id<3}));}}catch{state=structuredClone(init)}
let page='home',recordTab='meals',filter='全部',chatBusy=false,photoURL=null,entry={mode:'text',before:3},lastFocus=null;
function save(){try{localStorage.setItem('shike-v21',JSON.stringify(state))}catch{toast('浏览器存储空间不足，请先导出记录')}}
function resetQuota(){if(state.quota.date!==today())state.quota={date:today(),chat:0,photo:0}}resetQuota();
const english={home:'Overview',records:'Journal',assistant:'AI assistant',knowledge:'Health library',insights:'Mood insights',settings:'Settings',add:'Log a meal',title:'Every meal, thoughtfully cared for.',subtitle:'Food, water and feelings — a clearer picture of your day.',overview:'Daily energy',meals:'Today’s meals',water:'Hydration',quick:'Quick log',photo:'Photo',text:'Text',manual:'Manual',drink:'Water',goal:'Daily goals',general:'General',privacy:'Privacy & data',account:'Profile',membership:'Plan & usage',language:'Language',save:'Save settings',student:'Student'};const chinese={home:'今日概览',records:'饮食记录',assistant:'AI 助手',knowledge:'健康知识',insights:'心情洞察',settings:'我的设置',add:'记录一餐',title:'好好吃饭，也好好照顾自己。',subtitle:'饮食、饮水与心情，让每一天的健康更有条理。',overview:'今日能量概览',meals:'今日饮食',water:'饮水记录',quick:'快速记录',photo:'拍照识别',text:'文字记录',manual:'手动添加',drink:'记饮水',goal:'健康目标',general:'通用偏好',privacy:'隐私与数据',account:'个人资料',membership:'会员与额度',language:'界面语言',save:'保存设置'};const t=k=>(state.settings.language==='en'?english:chinese)[k]||chinese[k]||k;
const colors=['#3f8e78','#dfad64','#6f9eaf','#a6a2c2'];const moodFaces=['😞','🙁','😐','🙂','😊'];const moodNames=['低落','有些低落','平静','愉快','很开心'];
function data(){const ms=state.meals.filter(m=>m.date===today()),ws=state.water.filter(w=>w.date===today());return {ms,ws,cal:ms.reduce((s,m)=>s+(Number(m.cal)||0),0),protein:ms.reduce((s,m)=>s+(Number(m.protein)||0),0),carbs:ms.reduce((s,m)=>s+(Number(m.carbs)||0),0),fat:ms.reduce((s,m)=>s+(Number(m.fat)||0),0),water:ws.reduce((s,w)=>s+w.amount,0)}}
const btn=(label,action,cl='btn',attrs='')=>`<button class="${cl}" data-action="${action}" ${attrs}>${label}</button>`;
function head(title,sub,eyebrow='',action=''){return `<section class="hero"><div>${eyebrow?`<div class="eyebrow">${eyebrow}</div>`:''}<h1>${title}</h1><p>${sub}</p></div>${action}</section>`}
function title(text,icon='',right=''){return `<div class="heading"><div class="label">${icon?ic(icon):''}<h2>${text}</h2></div>${right}</div>`}function navigate(p){page=p;render();window.scrollTo({top:0,behavior:'instant'})}
function render(){resetQuota();document.documentElement.lang=state.settings.language==='en'?'en':'zh-CN';document.body.classList.toggle('compact',state.settings.compact);document.body.classList.toggle('hide-energy',state.settings.hideEnergy);const nav=[['home','home'],['records','record'],['assistant','spark'],['knowledge','book'],['insights','chart'],['settings','settings']];$('#app').innerHTML=`<div class="app"><aside class="sidebar"><div class="logo"><span class="logo-mark">${ic('leaf')}</span><div class="brandtext">食刻 AI<small>SHIKE · WELLNESS</small></div></div><div class="nav-section">你的健康空间</div><nav class="nav" aria-label="主导航">${nav.map(([p,i])=>`<button data-action="nav" data-page="${p}" class="${page===p?'active':''}" title="${t(p)}" ${page===p?'aria-current="page"':''}>${ic(i)}<span>${t(p)}</span>${['assistant','knowledge'].includes(p)?'<span class="new">NEW</span>':''}</button>`).join('')}</nav><div class="bottom"><div class="sidepro"><strong>食刻 Pro ✦</strong><p>更长的记录，更完整的理解。探索属于你的饮食与心情节奏。</p>${btn('探索 Pro 方案 →','pro')}</div><div class="version">DESIGNED WITH CARE · V2.1</div></div></aside><main class="main"><header class="topbar"><div class="breadcrumb">食刻 AI &nbsp;/&nbsp; <b>${t(page)}</b></div><div class="user"><span class="previewbadge">2.1 交互预览</span><span class="date small muted">${new Date().toLocaleDateString('zh-CN',{month:'long',day:'numeric',weekday:'long'})}</span>${btn(`<span class="avatar">${esc(state.settings.name.slice(0,1))}</span>`,'nav','',`data-page="settings" aria-label="我的设置"`)}</div></header>${({home:homePage,records:recordsPage,assistant:assistantPage,knowledge:knowledgePage,insights:insightsPage,settings:settingsPage}[page])()}</main><nav class="mobile-nav" aria-label="底部导航">${[['home','home'],['records','record'],['assistant','spark'],['knowledge','book'],['settings','user']].map(([p,i])=>`<button data-action="nav" data-page="${p}" class="${page===p?'active':''} ${p==='assistant'?'assistant-nav':''}" ${page===p?'aria-current="page"':''}>${ic(i)}<span>${t(p)}</span></button>`).join('')}</nav></div>`;if(page==='assistant'){const body=$('.chatbody');body.scrollTop=body.scrollHeight}}
function homePage(){const d=data(),s=state.settings,percent=Math.round(d.cal/s.calorieGoal*100),last=d.ms.filter(m=>m.after).at(-1);return `${head(t('title'),t('subtitle'),'YOUR DAILY WELLNESS',btn(ic('plus')+t('add'),'entry','btn primary'))}<div class="dashboard"><div class="stack"><div><section class="card">${title(t('overview'),'chart','<span class="tag">今日累计 · 可修改目标</span>')}<div class="energy"><div class="ring" style="--deg:${Math.min(100,percent)*3.6}deg"><div class="ring-label"><span>已记录摄入</span><strong class="mono energy-number">${d.cal.toLocaleString()}</strong><span>kcal / ${s.calorieGoal.toLocaleString()}</span><div><b class="tag">${percent}% 参考目标</b></div></div></div><div class="energy-info"><h3>${d.cal>s.calorieGoal?'高于参考目标':'距参考目标'}</h3><div><span class="big mono energy-number">${Math.abs(s.calorieGoal-d.cal)}</span> <span class="small muted">kcal</span></div><p>帮助理解摄入量，不用追求每餐精确。</p><div class="mealstack">${d.ms.map((m,i)=>`<i style="width:${m.cal/Math.max(d.cal,s.calorieGoal)*100}%;background:${colors[i%4]}"></i>`).join('')}</div><div class="legend">${d.ms.map((m,i)=>`<span style="--c:${colors[i%4]}">${esc(m.type)} ${m.cal??'—'}</span>`).join('')}</div></div></div><div class="nutrition">${[['蛋白质',d.protein,s.proteinGoal,'#67a596'],['碳水化合物',d.carbs,250,'#e1af6a'],['脂肪',d.fat,60,'#83a6bb']].map(([n,v,g,c])=>`<div><small>${n}</small><b class="mono">${v.toFixed(0)} <small>g</small></b><div class="track"><i style="width:${Math.min(100,v/g*100)}%;background:${c}"></i></div><small>${n==='蛋白质'?`参考目标 ${g}g`:'有填写的餐次合计'}</small></div>`).join('')}</div><div class="compare"><div class="comparetop"><b>把热量变成看得懂的刻度</b><span class="muted">1 格 = 100 kcal</span></div><div class="blocks">${Array.from({length:Math.ceil(Math.max(s.calorieGoal,d.cal)/100)},(_,i)=>`<i style="--fill:${Math.max(0,Math.min(100,d.cal-i*100))}%"></i>`).join('')}</div><div class="muted">已记录 ${Math.round(d.cal/100*10)/10} 格 / 目标 ${Math.round(s.calorieGoal/100*10)/10} 格 · 点击餐次查看贡献</div>${d.ms.length>=2&&d.ms[0].cal>0&&d.ms[1].cal>0?`<div class="meal-compare"><span>${d.ms[0].icon||'🍽️'} ${esc(d.ms[0].type)} <b>${d.ms[0].cal}</b></span><span class="compare-vs">对比</span><span>${d.ms[1].icon||'🍽️'} ${esc(d.ms[1].type)} <b>${d.ms[1].cal}</b></span></div><p class="small muted">这份${esc(d.ms[1].type)}的记录热量约为${esc(d.ms[0].type)}的 <b>${(d.ms[1].cal/d.ms[0].cal).toFixed(1)} 倍</b>，不代表营养价值高低。</p>`:''}</div></section><div class="quick-grid">${[['text','edit','文字记录'],['photo','camera','拍照识别'],['manual','plus','手动添加'],['water','water','记饮水']].map(([m,i,l])=>btn(`<span class="iconbox">${ic(i)}</span>${t(m==='water'?'drink':m)}`,m==='water'?'water':'entry','quick',`data-mode="${m}"`)).join('')}</div></div><section class="card">${title(t('meals'),'record',btn('全部记录 '+ic('arrow'),'nav','textbtn','data-page="records"'))}${mealList(d.ms)}<div class="footnote">${ic('shield')}演示记录带标记；你新增的记录保存在当前浏览器。</div></section><section class="card">${title('为你的生活多一点知识','book',btn('探索更多 →','nav','textbtn','data-page="knowledge"'))}${articles.slice(0,2).map(a=>`<button class="articleline" data-action="article" data-id="${a.id}"><div class="thumb">${a.emoji}</div><div><h3>${a.title}</h3><p>${a.category} · ${a.sourceName} · ${a.read} 分钟</p></div></button>`).join('')}</section></div><div class="stack"><section class="card watercard">${title(t('water'),'water',btn('详情 →','water','textbtn'))}${waterWidget(d)}</section><section class="card assistant-card">${title('食刻 AI 助手','',`<span class="assistantmark">${ic('spark')}</span>`)}<div class="contextline">${ic('check')} ${state.settings.aiContext?`已关联今天 ${d.ms.length} 餐 · ${d.ws.length} 次饮水`:'饮食上下文已关闭'}</div><p>忙着上课或工作，也能把今天的饮食整理清楚。试着问问：“帮我看看今天的记录。”</p>${btn('分析今天的饮食 '+ic('arrow'),'ask-today','btn')}<div class="small" style="font-size:9px;color:#8eafaa;margin-top:10px">AI 在线分析 · 连接失败时使用本地记录摘要</div></section><section class="card">${title('心情也值得被记录','',btn('看洞察 →','nav','textbtn','data-page="insights"'))}<div class="moodsummary"><div class="moodemoji">${last?moodFaces[(Number(last.after)||4)-1]:'😐'}</div><div><b>${last?`最近一餐：${moodNames[(Number(last.after)||4)-1]}`:'记录你的第一份感受'}</b><small>${last?`${last.type}后 ${last.score}/10 · 满意度 ${last.satisfaction}/5`:'餐前与餐后，感受有什么变化？'}</small></div></div>${moodSpark(d.ms)}<div class="infobox">先观察自己的感受，再慢慢建立适合自己的节奏。</div></section></div></div>`}
function mealList(ms){return ms.length?ms.slice().sort((a,b)=>b.time.localeCompare(a.time)).map(m=>`<button class="meal" data-action="detail" data-id="${m.id}"><div class="foodicon">${m.icon||'🍽️'}</div><div class="mealtext"><b>${esc(m.type)} · ${esc(m.food)}</b><small>${esc(m.time)} &nbsp; ${m.demo?'演示记录 · ':''}${m.after?`餐后 ${moodNames[(Number(m.after)||4)-1]}`:'待补充餐后感受'}</small></div><div class="mealvalue"><b class="energy-number">${m.cal??'—'}</b><small>kcal &nbsp;›</small></div></button>`).join(''):'<div class="empty">还没有记录。先从一餐开始吧。</div>'}
function waterWidget(d){let goal=state.settings.waterGoal,p=Math.min(100,d.water/goal*100);return `<div class="waterbody"><div class="wateramount"><strong class="mono">${d.water.toLocaleString()}</strong> <span class="small muted">/ ${goal} ml</span><p>约 ${(d.water/300).toFixed(1)} 杯 · 每杯按 300 ml 展示</p></div><div class="watercup" style="--water:${p}%" aria-label="饮水参考目标完成 ${Math.round(p)}%"></div></div><div class="cups" aria-hidden="true">${Array.from({length:Math.ceil(goal/300)},(_,i)=>`<i style="--fill:${Math.max(0,Math.min(100,(d.water-i*300)/3))}%"></i>`).join('')}</div><div class="wateractions">${btn('+ 200 ml','water-add','btn small','data-amount="200"')}${btn('+ 300 ml','water-add','btn small','data-amount="300"')}${btn('自定义','water','btn small')}</div>${state.settings.reminder?'<div class="footnote">分次记录，不必一次喝完。目标可在设置中调整。</div>':''}`}
function moodSpark(ms){let valid=ms.filter(m=>m.after&&m.score);if(!valid.length)return '<div class="empty small">保存餐后心情后，趋势会显示在这里。</div>';const pts=valid.slice(-7).map((m,i,a)=>[a.length===1?150:15+i*270/(a.length-1),70-m.score*6]);return `<svg class="spark" viewBox="0 0 300 80" role="img" aria-label="今天已记录餐后心情，分数${valid.map(m=>m.score).join('、')}"><path d="M10 70H290 M10 40H290 M10 10H290" stroke="#edf1ef" fill="none"/>${pts.length>1?`<polyline points="${pts.map(p=>p.join(',')).join(' ')}" fill="none" stroke="#64a98b" stroke-width="2.5"/>`:''}${pts.map((p,i)=>`<circle cx="${p[0]}" cy="${p[1]}" r="4" fill="#64a98b"/><text x="${p[0]}" y="${p[1]-10}" text-anchor="middle" font-size="10" fill="#6d8a7d">${valid.slice(-7)[i].score}</text>`).join('')}</svg>`}
function recordsPage(){const d=data();return `${head('每天的记录，都有迹可循。','从一顿饭、一杯水开始，慢慢拼出自己的生活节奏。','YOUR DAILY JOURNAL',btn(ic('plus')+t('add'),'entry','btn primary'))}<div class="tabs" role="tablist">${[['meals','饮食记录'],['water','饮水记录'],['mood','心情记录']].map(([id,label])=>btn(label,'record-tab',recordTab===id?'active':'',`data-tab="${id}" role="tab" aria-selected="${recordTab===id}"`)).join('')}</div>${recordTab==='meals'?`<div class="contentgrid"><section class="card">${title('今天','clock',`<span class="tag">${d.ms.length} 餐 · ${d.cal} kcal</span>`)}${mealList(d.ms)}${btn('＋ 补充一餐','entry','btn wide soft','style="margin-top:15px"')}</section><section class="card">${title('历史记录','record')}${state.meals.filter(m=>m.date!==today()).length?mealList(state.meals.filter(m=>m.date!==today())):'<div class="empty">从今天开始积累。<br>历史餐次会显示在这里。</div>'}<div class="infobox">每条记录都可以编辑食物、营养、花费以及餐前餐后心情。</div></section></div>`:recordTab==='water'?`<div class="contentgrid"><section class="card watercard">${title('今天喝了多少？','water')}${waterWidget(d)}</section><section class="card">${title('饮水时间线','clock')}${waterHistory(d.ws)}</section></div>`:insightsContent()}`}
function waterHistory(ws){return `<div class="water-history">${ws.length?ws.slice().reverse().map(w=>`<div class="waterlog"><span>💧 ${esc(w.time)} ${w.demo?'<span class="tag gray">演示</span>':''}</span><b>${w.amount} ml</b>${btn('撤销','water-remove','textbtn',`data-id="${w.id}"`)}</div>`).join(''):'<div class="empty">还没有饮水记录</div>'}</div>`}
function insightsPage(){return head('看见饮食，也看见自己的感受。','用餐前后的心情变化，值得被温柔地记录。','MOOD & FOOD')+insightsContent()}
function insightsContent(){const ms=data().ms.filter(m=>m.after&&m.score),avg=ms.length?(ms.reduce((s,m)=>s+m.score,0)/ms.length).toFixed(1):'—';return `<div class="contentgrid"><section class="card">${title('今日餐后心情','chart',`<span class="tag">平均 ${avg}/10</span>`)}${ms.length?`<div class="chartgrid">${ms.map(m=>`<div class="chartcol"><b>${m.score}/10</b><i style="height:${m.score*13}px"></i><small>${esc(m.type)} ${m.time}</small></div>`).join('')}</div>`:'<div class="empty">还没有餐后评分，点击餐次即可填写。</div>'}<div class="infobox">${ms.length} 条记录用于展示今天的感受。单日变化不能说明饮食与心情存在因果关系。</div></section><section class="card">${title('每餐的感受','leaf')}${mealList(data().ms)}${btn('查看 Pro 长期洞察','pro','btn wide soft','style="margin-top:15px"')}</section></div>`}
const sourceURL='https://www.who.int/news-room/fact-sheets/detail/healthy-diet';
const articles=[{id:1,title:'食堂怎么选，让一餐更丰富？',category:'校园饮食',emoji:'🥦 🍚',color:'#edf1df',sourceName:'WHO 健康膳食',read:2,summary:'从主食、蔬菜和蛋白质来源开始，少一点纠结，多一点搭配。',content:'在食堂点餐时，可以先看看这一餐是否包含不同食物类别。主食之外，搭配蔬菜和鸡蛋、鱼、肉或豆制品等蛋白质来源。<p>WHO 将充足、平衡、适度和多样性列为健康膳食的核心原则。这里的食堂搭配是把这些原则转成日常选餐思路，并非个人处方。</p>'},{id:2,title:'忙碌时，给饮食留一点准备',category:'职场日常',emoji:'🥪 🥛',color:'#e5edf2',sourceName:'生活实践',read:2,summary:'提前想好吃什么，给忙碌的学习和工作日留一点余地。',content:'这是生活安排建议：可以提前看看附近食堂或餐馆的营业时间，在日程中为吃饭留出空档；把常吃的食物存成自己的记录，会让补记更方便。<p>想让选择更丰富，可参考 WHO 的食物多样性原则，在不同餐次尝试蔬菜、水果、全谷物、豆类等食物。具体选择仍要考虑个人喜好和可获得的食物。</p>'},{id:3,title:'热量有用，但一餐不只有热量',category:'营养基础',emoji:'🍽️',color:'#f3eadb',sourceName:'WHO 健康膳食',read:2,summary:'看懂摄入数字，也留意食物种类、饱腹感和自己的感受。',content:'热量描述食物提供的能量，不会单独告诉你一餐的全部营养信息。阅读记录时，也可以留意食物种类和营养构成。<p>WHO 指出，适合个人的膳食组成与年龄、生活方式、活动量等因素有关。因此，本应用的默认目标是演示值，不能代表每个人的需要。</p>'},{id:4,title:'从食物种类开始认识碳水',category:'营养基础',emoji:'🌾 🫘',color:'#f0eedf',sourceName:'WHO 健康膳食',read:2,summary:'全谷物、蔬菜、水果和豆类，是了解碳水来源的起点。',content:'碳水化合物是身体的主要能量来源之一。WHO 建议碳水主要来自全谷物、蔬菜、水果和豆类。<p>记录时可以写下食物名称和份量，帮助自己回顾来源是否丰富。无需仅凭“含碳水”就评价一份食物。</p>'},{id:5,title:'记录压力，也记录吃饭的感受',category:'心情与饮食',emoji:'🫖 🌿',color:'#e7f0e7',sourceName:'记录方法',read:2,summary:'用餐前后各留一句话，找到自己想继续观察的地方。',content:'可以在餐前记录“正在赶作业”“今天会议很多”等情境，餐后再补充心情和满意度。日后回顾时，先描述发生了什么，再考虑哪些习惯值得调整。<p>这是一种自我记录方法，单次心情评分不能判断身体或心理疾病，也不能证明某种食物造成了情绪变化。</p>'},{id:6,title:'饮水记录，从认清杯子容量开始',category:'日常习惯',emoji:'💧',color:'#e4f0f6',sourceName:'产品使用指南',read:1,summary:'200 ml、300 ml，或自己的水杯容量，让记录更轻松。',content:'先查看自己的水杯容量，再使用相应的快捷按钮。喝了半杯，就记录约一半容量；误点可以在饮水时间线撤销。<p>首页“每杯 300 ml”只是统一显示刻度，不代表你的实际水杯大小。默认饮水目标仅用于预览，可在设置中修改。</p>'}];
function knowledgePage(){const visible=articles.filter(a=>filter==='全部'||filter==='已收藏'&&state.bookmarks.includes(a.id)||a.category===filter);return `${head('健康知识，认真了解一点点。','适合校园与工作日的阅读，每篇都说明内容来源。','THE WELLNESS LIBRARY')}<div class="knowledgehero"><div><div class="eyebrow">本周主题 · 吃得明白</div><h2>认识食物，比只盯着数字更丰富。</h2><p>从食堂搭配到忙碌日常，把知识放进真实生活。</p></div><div class="art" aria-hidden="true">🥑🥣</div></div><div class="filterrow">${['全部','校园饮食','职场日常','营养基础','心情与饮食','日常习惯','已收藏'].map(c=>btn(c,'filter',`filter ${filter===c?'active':''}`,`data-filter="${c}"`)).join('')}</div><div class="articles">${visible.map(a=>`<button class="article" data-action="article" data-id="${a.id}"><div class="article-art" style="--art-bg:${a.color}"><span class="art-label">SHIKE / KNOWLEDGE</span>${a.emoji}</div><div class="article-body"><span class="tag gray">${a.category}</span><h3>${a.title}</h3><p>${a.summary}</p><div class="article-meta"><span>${a.sourceName}</span><span>${a.read} 分钟 ${state.bookmarks.includes(a.id)?'★':''}</span></div></div></button>`).join('')}</div>${!visible.length?'<div class="empty">还没有收藏。在文章详情中点击“收藏”。</div>':''}`}
function assistantPage(){const d=data();return `${head('有问题，和食刻聊一聊。','从你记录的一日三餐出发，整理信息、回顾感受。','YOUR FOOD COMPANION')}<div class="assistant-layout"><section class="card chatcard"><div class="chathead"><div><h3>✦ 食刻 AI 助手</h3><p>${state.settings.aiContext?'已启用当天记录上下文':'未读取个人饮食上下文'}</p></div><span class="tag orange">${chatBusy?'正在回复…':'AI 助手'}</span></div><div class="chatbody" aria-live="polite">${!state.chat.length?`<div class="chatintro"><div class="assistantmark">${ic('spark')}</div><h2>今天，想从哪里开始？</h2><p>你记下的一餐、一杯水、一份感受，<br>都可以成为对话的起点。</p><div class="suggestions">${['帮我分析今天的饮食','今天喝了多少水？','回顾餐后心情','上课或工作太忙怎么记录？'].map(q=>btn(q,'ask','',`data-question="${q}"`)).join('')}</div></div>`:state.chat.map(m=>`<div class="message ${m.role==='user'?'user':''}">${m.role==='assistant'?`<div class="message-label">食刻 · ${m.source==='remote'?'AI 助手':'本地记录摘要'}</div>`:''}${esc(m.text)}</div>`).join('')}</div><form class="composer" id="chat-form"><input name="question" aria-label="向 AI 助手提问" placeholder="问问今天的饮食、饮水或心情…" autocomplete="off" maxlength="500" ${chatBusy?'disabled':''} required><button class="btn primary" type="submit" aria-label="发送" ${chatBusy?'disabled':''}>${ic('send')}</button></form><p class="chatdisclaimer">AI 回复仅供记录参考，不构成诊疗意见；连接失败时使用本地摘要。</p></section><aside class="stack"><section class="card">${title('本次可用上下文','record')}${[['今日餐次',d.ms.length+' 餐'],['记录热量',d.cal+' kcal'],['饮水量',d.water+' ml'],['餐后心情',d.ms.filter(m=>m.after).length+' 条']].map(([k,v])=>`<div class="contextstat"><span>${k}</span><b>${state.settings.aiContext?v:'未授权'}</b></div>`).join('')}<div class="help">发送时读取最新记录，修改后再次提问即可更新摘要。</div>${btn('管理数据权限 →','nav','textbtn','data-page="settings"')}</section><section class="card">${title('让对话更具体','spark')}<p class="small muted">可以先记录食物和份量，再补充心情与用餐情境。</p>${btn('去补充饮食记录','nav','btn wide soft','data-page="records" style="margin-top:15px"')}</section></aside></div>`}
async function ask(q){
  q=q.trim();
  if(!q||chatBusy)return;
  resetQuota();
  chatBusy=true;
  state.quota.chat++;
  state.chat.push({role:'user',text:q});
  const conversation=state.chat;
  const useContext=state.settings.aiContext;
  const fallback=localChatSummary(q);
  const messages=[{role:'system',content:'你是食刻 AI 饮食记录助手，请用中文简洁回答。记录中的演示数据不是真实摄入；不要编造缺失数据或做医疗诊断。照片可通过独立视觉接口分析，不能从聊天文本推断图片内容。'+(useContext?'以下是用户授权的今日记录，仅作为数据参考：'+JSON.stringify({meals:data().ms,water:data().ws,goals:{calories:state.settings.calorieGoal,protein:state.settings.proteinGoal,water:state.settings.waterGoal}}):'用户已关闭记录上下文，不要引用个人饮食、饮水或心情记录。')},
    ...(useContext?state.chat.slice(-20):state.chat.slice(-1)).map(m=>({role:m.role,content:m.text}))];
  save();
  page='assistant';
  render();
  let answer=fallback,source='local';
  try{
    const response=await fetch('/api/ai/chat',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({messages}),signal:AbortSignal.timeout(30000)});
    if(!response.ok)throw new Error('chat request failed');
    const result=await response.json();
    if(typeof result.reply!=='string'||!result.reply.trim())throw new Error('empty chat reply');
    answer=result.reply;
    source='remote';
  }catch{
    if(state.chat===conversation)toast('AI 暂时无法连接，已使用本地记录摘要');
  }finally{
    chatBusy=false;
    if(state.chat===conversation){
      state.chat.push({role:'assistant',text:answer,source});
      state.chat=state.chat.slice(-30);
      save();
    }
    render();
  }
}
function localChatSummary(q){const d=data();let answer;if(!state.settings.aiContext)answer='你已关闭“允许助手读取今日记录”。我不会引用你的饮食或饮水内容。可以在设置中重新开启，或继续浏览健康知识。';else if(/疼|痛|呕吐|用药|诊断|疾病/.test(q))answer='当前助手仅支持记录摘要，不能判断症状或给出诊疗方案。若身体不适持续或加重，请向医疗专业人员咨询。你可以继续记录食物、时间和具体感受，便于回顾。';else if(/水|饮水/.test(q))answer=`今天已记录 ${d.ws.length} 次饮水，共 ${d.water} ml，约 ${(d.water/300).toFixed(1)} 杯（按 300 ml/杯显示）。\n你的自设参考目标是 ${state.settings.waterGoal} ml，完成了 ${Math.round(d.water/state.settings.waterGoal*100)}%。这个目标是当前设置值，不是对你个人需求的评估。\n可以使用首页快捷按钮补记；误点的记录可在时间线撤销。`;else if(/心情|情绪|压力/.test(q)){const ms=d.ms.filter(m=>m.after);answer=ms.length?`今天有 ${ms.length} 条餐后心情记录：\n${ms.map(m=>`${m.type}：${moodNames[(Number(m.after)||4)-1]}，${m.score}/10，满意度 ${m.satisfaction}/5。`).join('\n')}\n目前只展示你填写的感受，无法据此判断某种食物与心情的因果关系。下次也可以补充当时的学习或工作情境。`:'今天还没有餐后心情记录。打开任意餐次，补充餐后感受、心情分数和满意度，我就可以帮你整理。'}else if(/忙|工作|上课/.test(q))answer='忙碌时可以先用文字写下“餐次＋食物”，有空再补充份量与感受。\n拍照入口现在先显示上传按钮，选择照片后尝试 AI 分析并填表，失败时可手动填写。\n记饮水只需点一次快捷按钮，填错后可撤销。你也可以在健康知识中查看校园与职场主题。';else if(/分析|今天|饮食|吃|记录|总结/.test(q))answer=`根据今天已保存的记录：\n${d.ms.length?d.ms.map(m=>`• ${m.type} ${m.time}：${m.food}（${m.cal??'未填'} kcal）`).join('\n'):'还没有饮食记录。'}\n已填写热量合计 ${d.cal} kcal，蛋白质 ${d.protein} g。饮水 ${d.water} ml。\n${d.ms.some(m=>m.cal===null)?'部分餐次缺少热量，合计并不完整。':'这些数值来自你填写或保留的演示记录，不是自动营养识别结果。'}\n下一步可以核对份量、补齐未记录的餐次，再记录餐后感受。不能仅凭现有记录判断营养是否充足。`;else answer='当前是本地交互演示，我能整理今天的饮食、饮水和餐后心情。试试“分析今天的饮食”或“回顾餐后心情”。开放式问答将在后续接入大模型后提供。';return answer;}
function settingsPage(){const s=state.settings;return `${head('把食刻，调成适合你的样子。','个人资料、通用偏好、目标与使用额度，都在这里。','SETTINGS & PREFERENCES')}<form id="settings-form"><div class="settings-grid"><div class="stack"><section class="card">${title(t('account'),'user')}<div class="profilecard"><div class="avatar">${esc(s.name.slice(0,1))}</div><div><h3>${esc(s.name)}</h3><p class="small muted">${esc(s.role)} · 当前浏览器个人空间</p></div></div><div class="settings-row"><label for="name">昵称</label><input id="name" name="name" value="${esc(s.name)}" maxlength="20" required style="width:145px"></div><div class="settings-row"><label for="role">生活状态</label><select id="role" name="role">${['在校学生','职场工作者','关注饮食健康','其他'].map(v=>`<option ${s.role===v?'selected':''}>${v}</option>`).join('')}</select></div></section><section class="card">${title(t('general'),'settings')}<div class="settings-row"><div><label for="language">${t('language')}</label><p>英文为导航与设置标题预览，文章保留中文</p></div><select id="language" name="language"><option value="zh" ${s.language==='zh'?'selected':''}>简体中文</option><option value="en" ${s.language==='en'?'selected':''}>English · Preview</option></select></div>${settingToggle('compact','紧凑布局','减小卡片内边距，显示更多信息',s.compact)}${settingToggle('hideEnergy','弱化热量数字','模糊数字并隐藏刻度，保留饮食记录',s.hideEnergy)}${settingToggle('reminder','饮水温馨提示','显示页面内提示，不发送系统通知',s.reminder)}</section><section class="card">${title(t('goal'),'leaf')}${[['calorieGoal','每日热量参考','kcal',500,5000],['proteinGoal','蛋白质参考','g',10,300],['waterGoal','饮水参考','ml',300,5000]].map(([k,l,u,min,max])=>`<div class="settings-row"><label for="${k}">${l} <span class="muted small">${u}</span></label><input id="${k}" name="${k}" type="number" value="${s[k]}" min="${min}" max="${max}" required></div>`).join('')}<p class="help">初始数值用于演示，不是个体营养建议。请按实际需要设定目标。</p></section></div><div class="stack"><section class="card">${title(t('membership'),'spark','<span class="tag gray">FREE · 演示</span>')}<p class="small muted">以下为 2.1 产品方案草案，非正式套餐承诺。</p><div class="pro-banner"><h2>为更长期的了解，升级 Pro</h2><p>规划中的权益：更多分析次数、长期心情趋势与每周回顾。</p>${btn('查看 Pro 权益 →','pro','btn small')}</div>${[['AI 对话演示',state.quota.chat,10],['拍照流程演示',state.quota.photo,5]].map(([l,n,max])=>`<div class="quota"><div class="quota-label"><b>${l}</b><span>${n} / ${max} 次</span></div><div class="track"><i style="width:${Math.min(100,n/max*100)}%"></i></div><small>今日剩余 ${Math.max(0,max-n)} 次</small></div>`).join('')}<div class="infobox">演示额度每日按设备本地日期重置。下次：${nextReset()}。文字、手动和饮水记录不限次。</div></section><section class="card">${title(t('privacy'),'shield')}${settingToggle('aiContext','允许助手读取今日记录','开启后将今日记录发送给 AI；关闭后不发送记录和历史对话',s.aiContext)}<div class="settings-row"><div><strong>存储方式</strong><p>记录保存在当前浏览器；上传的照片仅用于 AI 分析</p></div><span class="tag gray">本地</span></div><div class="settings-row"><div><strong>导出我的记录</strong><p>下载饮食、饮水、设置和心情数据</p></div>${btn('导出 JSON','export','btn small')}</div><div class="settings-row"><div><strong>清空本地数据</strong><p>删除当前浏览器中的记录与对话</p></div>${btn('清空','clear-confirm','btn small danger')}</div></section><section class="card">${title('帮助与关于','book')}<div class="settings-row"><strong>使用说明与反馈</strong>${btn('查看 →','help','textbtn')}</div><div class="settings-row"><strong>食刻 AI</strong><span class="muted small">2.1 交互预览</span></div></section></div></div><button class="btn primary" type="submit" style="margin-top:22px;min-width:170px">${ic('check')}${t('save')}</button></form>`}
function settingToggle(name,label,sub,value){return `<div class="settings-row"><div><label for="${name}">${label}</label><p>${sub}</p></div><input class="switch" id="${name}" name="${name}" type="checkbox" role="switch" ${value?'checked':''}></div>`}function nextReset(){let d=new Date();d.setDate(d.getDate()+1);return `${d.getMonth()+1}月${d.getDate()}日 00:00`}
function modal(titleText,body,footer=''){lastFocus=document.activeElement;const dlg=$('#dialog');dlg.innerHTML=`<div class="modal-head"><h2 id="dialog-title">${titleText}</h2>${btn(ic('close'),'close','close','aria-label="关闭"')}</div><div class="modal-body">${body}</div>${footer?`<div class="modal-footer">${footer}</div>`:''}`;if(!dlg.open)dlg.showModal();document.body.classList.add('modal-open');dlg.scrollTop=0;const c=dlg.querySelector('.close');c?.focus({preventScroll:true})}function closeModal(){const dlg=$('#dialog');dlg.close();document.body.classList.remove('modal-open');if(photoURL){URL.revokeObjectURL(photoURL);photoURL=null}lastFocus?.focus?.({preventScroll:true})}$('#dialog').addEventListener('close',()=>document.body.classList.remove('modal-open'));$('#dialog').addEventListener('click',e=>{if(e.target===$('#dialog'))closeModal()});
let toastTimer;function toast(msg){clearTimeout(toastTimer);$('#toast').className='toast';$('#toast').textContent=msg;toastTimer=setTimeout(()=>{$('#toast').className='';$('#toast').textContent=''},3200)}
function startEntry(mode='text'){entry={mode,before:3};if(photoURL){URL.revokeObjectURL(photoURL);photoURL=null}mode==='photo'?photoStep():mealForm()}
function photoStep(){modal('拍照记录',`<div class="steps"><span class="active">① 选择照片</span><span>② 确认与保存</span></div><div id="photo-container"><div class="uploadzone">${ic('camera')}<h2>把这一餐，拍下来。</h2><p>让食物尽量完整地出现在画面里</p><div class="uploadbuttons">${btn(ic('upload')+'上传照片','choose-photo','btn primary')}${btn(ic('camera')+'拍照','take-photo','btn')}</div></div></div><input id="photo-file" type="file" accept="image/jpeg,image/png,image/gif,image/webp" hidden><input id="photo-camera" type="file" accept="image/*" capture="environment" hidden><p class="help">支持 JPEG、PNG、GIF、WebP；建议不超过 15 MB。照片将发送至服务端 AI 分析，营养结果仅供估算。</p><div class="modal-note">选择照片后自动分析并填写表单；分析失败时可继续手动填写。</div><p class="small muted">今日拍照流程演示：剩余 ${Math.max(0,5-state.quota.photo)} / 5 次</p>`,btn('继续填写 '+ic('arrow'),'photo-next','btn primary','id="photo-next" disabled'))}
function handlePhoto(file){if(!file)return;if(file.size>15*1024*1024){toast('照片超过 15 MB，请选择较小的文件');return}if(!file.type.startsWith('image/')&&!/\.(heic|heif)$/i.test(file.name)){toast('请选择图片文件');return}if(photoURL)URL.revokeObjectURL(photoURL);photoURL=URL.createObjectURL(file);entry.photoName=file.name;$('#photo-container').innerHTML=`<img class="photo-preview" src="${photoURL}" alt="所选食物照片预览"><p class="help">${esc(file.name)} · ${(file.size/1024/1024).toFixed(1)} MB</p>${btn('重新选择','choose-photo','btn small')}`;$('.photo-preview').onerror=()=>{$('#photo-container').innerHTML=`<div class="modal-note">已选择 ${esc(file.name)}。当前浏览器无法预览此图片格式，可以继续手动填写，或改用 JPG。</div>${btn('重新选择','choose-photo','btn small')}`};$('#photo-next').disabled=false;analyzePhoto(file)}
async function analyzePhoto(file){
  const current=entry,request=Symbol();
  current.photoRequest=request;
  delete current.analysis;
  const active=()=>entry===current&&entry.photoRequest===request&&$('#photo-next')&&$('#dialog').open;
  const status=document.createElement('p');
  status.className='photo-status';
  status.setAttribute('role','status');
  status.textContent='正在分析照片…也可以直接继续手动填写。';
  $('#photo-container').append(status);
  try{
    if(!['image/jpeg','image/png','image/gif','image/webp'].includes(file.type))throw new Error('此格式暂不支持 AI 分析，请改用 JPEG、PNG、GIF、WebP 或手动填写。');
    const image=await new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(reader.result);reader.onerror=()=>reject(new Error('图片读取失败，请手动填写。'));reader.readAsDataURL(file)});
    if(!active())return;
    const response=await fetch('/api/ai/analyze-food',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({image}),signal:AbortSignal.timeout(50000)});
    const result=await response.json();
    if(!response.ok)throw new Error(response.status===503?'图片分析服务尚未配置，请手动填写。':'图片分析失败，请手动填写。');
    if(typeof result.food!=='string'||!result.food.trim()||result.food.length>600||Object.entries({cal:20000,protein:1000,carbs:2000,fat:2000}).some(([k,max])=>typeof result[k]!=='number'||!Number.isFinite(result[k])||result[k]<0||result[k]>max))throw new Error('图片分析结果无效，请手动填写。');
    if(!active())return;
    current.analysis={food:result.food,cal:result.cal,protein:result.protein,carbs:result.carbs,fat:result.fat};
    state.quota.photo++;
    save();
    mealForm();
  }catch(error){
    if(active())status.textContent=(error.message.startsWith('此格式')||error.message.startsWith('图片分析服务尚未配置'))?error.message:'图片分析未完成，请继续手动填写，或重新选择照片。';
  }
}
function mealForm(existing=null){if(existing){entry={mode:'edit',before:Number(existing.before)||3,id:existing.id}}const m=existing||entry.analysis||{},photo=entry.mode==='photo',sample=entry.sample;const food=sample?'米饭 150g、鸡胸肉 120g、西兰花 100g':m.food||'';modal(existing?`${esc(m.type)} · 记录详情`:photo?'确认这一餐':entry.mode==='manual'?'手动添加食物':'文字记录',`${photo?'<div class="steps"><span>✓ 选择照片</span><span class="active">② 确认与保存</span></div>':''}${sample?'<div class="modal-note">以下是流程示例，未分析你的照片。热量与营养仅为演示数值，请修改后保存。</div>':photo?`<div class="modal-note">${entry.analysis?'AI 已填入食物和营养估算，请核对份量并修改后保存。':'图片分析未完成，请手动填写食物和营养。'}</div>`:''}<form id="meal-form"><div class="fields"><div class="field"><label for="meal-type">餐次</label><select name="type" id="meal-type">${['早餐','午餐','晚餐','加餐'].map(v=>`<option ${(m.type||'午餐')===v?'selected':''}>${v}</option>`).join('')}</select></div><div class="field"><label for="meal-time">时间</label><input type="time" id="meal-time" name="time" value="${m.time||timeNow()}" required></div></div><div class="field"><label for="meal-food">${entry.mode==='text'?'这一餐吃了什么？':'食物名称与份量'}</label><textarea id="meal-food" name="food" placeholder="例如：米饭一碗、番茄炒蛋、清炒青菜" maxlength="600" required>${esc(food)}</textarea></div><div class="fields"><div class="field"><label for="meal-cal">热量 kcal · 可留空</label><input id="meal-cal" name="cal" type="number" min="0" max="20000" step="1" placeholder="未填写" value="${sample?620:m.cal??''}"></div><div class="field"><label for="meal-protein">蛋白质 g · 可留空</label><input id="meal-protein" name="protein" type="number" min="0" max="1000" step="0.1" placeholder="未填写" value="${sample?36:m.protein??''}"></div></div><div class="field"><label>餐前心情</label><div class="moodoptions">${moodFaces.map((f,i)=>btn(`<span>${f}</span>${moodNames[i]}`,'mood-option',entry.before===i+1?'selected':'',`data-value="${i+1}" aria-pressed="${entry.before===i+1}"`)).join('')}</div></div>${existing?`<div class="field"><label for="after">餐后心情</label><select name="after" id="after"><option value="">暂未记录</option>${moodNames.map((n,i)=>`<option value="${i+1}" ${Number(m.after)===i+1?'selected':''}>${moodFaces[i]} ${n}</option>`).join('')}</select></div><div class="field"><label class="range-label" for="score">餐后心情量化值 <span><output id="score-out">${m.score||5}</output> / 10</span></label><input id="score" name="score" type="range" min="1" max="10" value="${m.score||5}"></div><div class="field"><label class="range-label" for="satisfaction">用餐满意度 <span><output id="satisfaction-out">${m.satisfaction||3}</output> / 5</span></label><input id="satisfaction" name="satisfaction" type="range" min="1" max="5" value="${m.satisfaction||3}"></div>`:''}<details class="details" ${existing||entry.analysis?'open':''}><summary>补充信息 · 花费、时长与营养</summary><div class="fields"><div class="field"><label for="cost">花费 ¥</label><input id="cost" name="cost" type="number" min="0" max="100000" step="0.01" value="${m.cost??''}" placeholder="可选"></div><div class="field"><label for="duration">用餐时长（分钟）</label><input id="duration" name="duration" type="number" min="0" max="1440" value="${m.duration??''}" placeholder="可选"></div><div class="field"><label for="carbs">碳水化合物 g</label><input id="carbs" name="carbs" type="number" min="0" max="2000" step="0.1" value="${m.carbs??''}" placeholder="可选"></div><div class="field"><label for="fat">脂肪 g</label><input id="fat" name="fat" type="number" min="0" max="2000" step="0.1" value="${m.fat??''}" placeholder="可选"></div></div><div class="field"><label for="note">用餐感受 / 备注</label><textarea id="note" name="note" maxlength="600" placeholder="例如：今天赶作业，吃得有点急">${esc(m.note||'')}</textarea></div></details></form>`,(existing?btn('删除记录','delete-meal-confirm','btn danger',`data-id="${m.id}"`):'')+`<button class="btn primary" type="submit" form="meal-form">${ic('check')}${existing?'保存修改':'保存这一餐'}</button>`)}
function waterModal(){const d=data();modal('记录一杯水',`<section class="watercard" style="padding:18px;border-radius:12px">${waterWidget(d)}</section><div class="amountchoices">${[150,250,500].map(n=>btn('＋ '+n+' ml','water-add','btn',`data-amount="${n}"`)).join('')}</div><form id="water-form"><div class="field"><label for="custom-water">自定义容量（ml）</label><input id="custom-water" name="amount" type="number" min="10" max="2000" step="10" placeholder="输入本次喝水量" required></div><button class="btn primary wide" type="submit">添加饮水记录</button></form><div style="margin-top:24px">${title('今天的饮水时间线','clock')}${waterHistory(d.ws)}</div>`)}
function addWater(n){if(!Number.isFinite(n)||n<10||n>2000){toast('请输入 10–2000 ml 的本次饮水量');return}state.water.push({id:Date.now(),date:today(),time:timeNow(),amount:n});save();render();if($('#dialog').open)waterModal();toast(`已记录 ${n} ml，可在饮水时间线撤销`)}
function articleModal(id){const a=articles.find(x=>x.id===id);if(!a)return;modal(a.title,`<div class="article-art" style="--art-bg:${a.color};border-radius:12px">${a.emoji}</div><div class="articlecontent"><div class="help">${a.category} · ${a.read} 分钟 · ${a.sourceName}</div><p>${a.content}</p>${a.sourceName.includes('WHO')||a.id===2?`<div class="infobox">来源：WHO《Healthy diet》。中文内容为简要转述，生活场景举例为编辑整理。</div><p><a href="${sourceURL}" target="_blank" rel="noopener noreferrer">阅读 WHO 原文 ↗</a></p>`:'<div class="infobox">食刻编辑整理 · 生活记录与产品使用方法，不是医学诊断。</div>'}</div>`,btn(state.bookmarks.includes(id)?'★ 已收藏 · 点击取消':'☆ 收藏文章','bookmark','btn',`data-id="${id}"`)+btn('阅读完成','close','btn primary'))}
function proModal(){modal('食刻 Pro · 方案预览',`<div class="pro-banner" style="margin-top:0"><div class="eyebrow" style="color:#d2e8b7">GROW WITH YOUR EVERYDAY</div><h2>更长的记录，更完整的理解。</h2><p>围绕饮食与情绪的长期观察，设计真正有用的权益。</p></div><table class="plan-table"><thead><tr><th>能力</th><th>Free 草案</th><th>Pro 草案</th></tr></thead><tbody><tr><td>文字 / 手动 / 饮水记录</td><td>不限次</td><td>不限次</td></tr><tr><td>AI 对话</td><td>10 次 / 日</td><td>100 次 / 日</td></tr><tr><td>拍照识别</td><td>5 次 / 日</td><td>50 次 / 日</td></tr><tr><td>餐后心情与满意度</td><td>支持</td><td>支持</td></tr><tr><td>长期趋势、每周回顾</td><td>基础查看</td><td>计划支持</td></tr></tbody></table><p class="help">套餐与额度均为本次设计草案，尚未开通订阅或付款。当前额度只计数演示操作。</p>`,btn('查看当前额度','quota','btn primary'))}
function helpModal(){modal('使用说明与反馈',`<div class="articlecontent"><h3>这版可以体验什么？</h3><p>添加和编辑饮食、记录饮水与心情、阅读并收藏科普文章，以及使用当天记录生成本地摘要。</p><h3>照片和 AI 回复如何处理？</h3><p>照片会通过服务端发送给视觉模型，返回食物和营养估算；失败时可手动填写。助手通过服务端调用 AI；连接失败时使用本地规则摘要。开启记录上下文后，今日记录会发送给 AI 用于回答。</p><h3>为什么刷新后还有记录？</h3><p>数据保存在当前浏览器。清理浏览器数据或更换设备后不会自动同步，重要记录可以先导出。</p><h3>提出设计反馈</h3><p>回到我们正在进行的对话，告诉我页面名称、操作步骤和希望改成的效果即可。</p></div>`,btn('知道了','close','btn primary'))}
document.addEventListener('click',e=>{const el=e.target.closest('[data-action]');if(!el)return;e.preventDefault();const a=el.dataset.action,id=Number(el.dataset.id);switch(a){case'nav':navigate(el.dataset.page);break;case'entry':startEntry(el.dataset.mode||'text');break;case'close':closeModal();break;case'choose-photo':$('#photo-file').click();break;case'take-photo':$('#photo-camera').click();break;case'photo-next':if(!entry.photoName)return;if(false){toast('今日拍照流程演示额度已用完');return}entry.photoRequest=null;save();mealForm();break;case'sample-photo':if(false){toast('今日拍照流程演示额度已用完');return}state.quota.photo++;save();entry.sample=true;mealForm();break;case'mood-option':entry.before=Number(el.dataset.value);document.querySelectorAll('.moodoptions button').forEach(b=>{const active=Number(b.dataset.value)===entry.before;b.classList.toggle('selected',active);b.setAttribute('aria-pressed',String(active))});break;case'detail':{const m=state.meals.find(m=>m.id===id);if(m)mealForm(m);break}case'water':waterModal();break;case'water-add':addWater(Number(el.dataset.amount));break;case'water-remove':state.water=state.water.filter(w=>w.id!==id);save();render();if($('#dialog').open)waterModal();toast('已撤销这次饮水记录');break;case'record-tab':recordTab=el.dataset.tab;render();break;case'filter':filter=el.dataset.filter;render();break;case'article':articleModal(id);break;case'bookmark':state.bookmarks=state.bookmarks.includes(id)?state.bookmarks.filter(i=>i!==id):[...state.bookmarks,id];save();render();articleModal(id);break;case'ask':ask(el.dataset.question);break;case'ask-today':ask('帮我分析今天的饮食');break;case'pro':proModal();break;case'quota':closeModal();navigate('settings');break;case'help':helpModal();break;case'export':{const blob=new Blob([JSON.stringify({...state,exportedAt:new Date().toISOString()},null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),link=document.createElement('a');link.href=url;link.download=`食刻AI-记录-${today()}.json`;link.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('已生成记录文件');break}case'clear-confirm':modal('清空本地数据？','<p>此操作会删除当前浏览器中的饮食、饮水、心情、对话和设置，无法撤销。可先返回设置导出记录。</p>',btn('取消','close','btn')+btn('确认清空','clear','btn danger'));break;case'clear':state=structuredClone(init);state.meals=[];state.water=[];state.chat=[];state.bookmarks=[];state.quota={date:today(),chat:0,photo:0};try{localStorage.removeItem('shike-meals-v2')}catch{}save();closeModal();render();toast('已清空本地数据');break;case'delete-meal-confirm':modal('删除这条饮食记录？','<p>这条记录中的食物、营养与心情数据将一并删除。</p>',btn('取消','cancel-delete','btn',`data-id="${id}"`)+btn('确认删除','delete-meal','btn danger',`data-id="${id}"`));break;case'cancel-delete':mealForm(state.meals.find(m=>m.id===id));break;case'delete-meal':state.meals=state.meals.filter(m=>m.id!==id);save();closeModal();render();toast('记录已删除');break;}});
document.addEventListener('change',e=>{if(e.target.id==='photo-file'||e.target.id==='photo-camera')handlePhoto(e.target.files[0])});document.addEventListener('input',e=>{if(['score','satisfaction'].includes(e.target.id))$('#'+e.target.id+'-out').value=e.target.value});
document.addEventListener('submit',e=>{if(!['meal-form','water-form','settings-form','chat-form'].includes(e.target.id))return;e.preventDefault();const f=new FormData(e.target);if(e.target.id==='meal-form'){const food=String(f.get('food')).trim();if(!food){toast('请填写食物内容');return}const prev=entry.id?state.meals.find(m=>m.id===entry.id):null;const number=k=>f.get(k)===null||f.get(k)===''?null:Number(f.get(k));const m={...(prev||{}),id:prev?.id||Date.now(),date:prev?.date||today(),time:f.get('time'),type:f.get('type'),food,cal:number('cal'),protein:number('protein'),carbs:number('carbs'),fat:number('fat'),cost:number('cost'),duration:number('duration'),before:entry.before,after:number('after'),score:number('score'),satisfaction:number('satisfaction'),note:f.get('note')||'',icon:f.get('type')==='早餐'?'🥪':f.get('type')==='加餐'?'🍎':'🥗',demo:entry.sample||prev?.demo||false};if(prev)state.meals=state.meals.map(x=>x.id===m.id?m:x);else state.meals.push(m);save();closeModal();render();toast(prev?'记录已更新':'这一餐已保存，可在详情中补充餐后感受')}else if(e.target.id==='water-form')addWater(Number(f.get('amount')));else if(e.target.id==='chat-form')ask(String(f.get('question')));else if(e.target.id==='settings-form'){const name=String(f.get('name')).trim();if(!name){toast('请输入昵称');return}Object.assign(state.settings,{name,role:f.get('role'),language:f.get('language'),calorieGoal:Number(f.get('calorieGoal')),proteinGoal:Number(f.get('proteinGoal')),waterGoal:Number(f.get('waterGoal')),compact:f.has('compact'),hideEnergy:f.has('hideEnergy'),reminder:f.has('reminder'),aiContext:f.has('aiContext')});save();render();toast('设置已保存')}});
render();
